export type DownloadDocumentFileData = {
  body?: never
  headers: {
    /**
     * Client supplied name of the calling service. This should be the product name of the service as listed in the developer portal
     */
    'Service-Name': string
    /**
     * The active case load id of the user interacting with the client service
     */
    'Active-Case-Load-Id'?: string
    /**
     * The username of the user interacting with the client service
     */
    Username?: string
  }
  path: {
    /**
     * Document unique identifier
     */
    documentUuid: string
  }
  query?: {
    /**
     * When true, serves the file with Content-Disposition: inline so it renders in the browser instead of downloading. Only honoured for PDFs; any other type falls back to attachment. Defaults to false.
     */
    inline?: boolean
  }
  url: '/documents/{documentUuid}/file'
}

export type DownloadDocumentFileErrors = {
  /**
   * Unauthorised, requires a valid Oauth2 token
   */
  401: ErrorResponse
  /**
   * Forbidden, requires an appropriate role. Note that the required role can be document type dependent
   */
  403: ErrorResponse
  /**
   * The document file associated with this unique identifier was not found.
   */
  404: ErrorResponse
}

export type DownloadDocumentFileError = DownloadDocumentFileErrors[keyof DownloadDocumentFileErrors]

export type DownloadDocumentFileResponses = {
  /**
   * Document file found
   */
  200: Blob | File
}

export type DownloadDocumentFileResponse = DownloadDocumentFileResponses[keyof DownloadDocumentFileResponses]

